// Pegar a primeira linha que NÃO tem status "ok"
const items = $input.all();
const config = $('Config').first().json;

let found = null;
let rowIndex = -1;

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const status = (item.status || item.Status || '').toString().trim().toLowerCase();

  if (status !== 'ok' && status !== 'done' && status !== 'publicado') {
    found = item;
    // usar o numero real da linha na planilha (row_number) para marcacao exata
    rowIndex = (item.row_number != null) ? item.row_number : (i + 2);
    break;
  }
}

if (!found) {
  // Nenhuma linha pendente - parar execucao
  return [];
}

const curso = found['Nome do Curso'] || found.curso || found.Curso || '';
const link = found['link do curso no site'] || found.link || found.Link || '';

if (!curso || !link) {
  throw new Error('Linha ' + rowIndex + ' sem curso ou link. Colunas: ' + Object.keys(found).join(', '));
}

return [{ json: {
  curso,
  link,
  rowIndex,
  apiKey: config.ANTHROPIC_API_KEY,
  wpUrl: config.WORDPRESS_URL,
  sheetsUrl: config.GOOGLE_SHEETS_URL,
  systemPromptB64: config.SYSTEM_PROMPT_B64
}}];

const data = $input.first().json;
const curso = data.curso;
const link = data.link;

const userPrompt = `Quero criar uma página de blog completa sobre a profissão: ${curso}

URL do curso na UFEM: ${link}

<OBJETIVO>
Este agente tem como missão realizar pesquisas profundas e organizadas na internet para auxiliar criadores de conteúdo na elaboração de páginas de blog completas e informativas sobre a profissão proposta. Ele investiga as principais fontes digitais para mapear os temas mais abordados, dúvidas mais comuns do público e oportunidades de explicação. O foco está em entregar um dossiê estratégico com TODOS os dados necessários para gerar uma página de mercado de trabalho.
</OBJETIVO>

<LIMITACOES>
* Não deve inventar dados ou simular pesquisas.
* Todos os dados devem vir de fontes reais e verificáveis.
</LIMITACOES>

<INSTRUCOES>
1. Busque em YouTube (20 vídeos + comentários), Reddit, blogs, CAGED, RAIS, Salario.com.br, Glassdoor, Vagas.com, conselhos profissionais, IBGE, MEC, ANVISA.

2. YouTube: encontre 20 vídeos relevantes, classifique os 20 temas mais comuns, identifique 20 dúvidas recorrentes nos comentários preservando expressões exatas.

3. Reddit: tópicos, dúvidas, reclamações, elogios e padrões.

4. Blogs: tópicos recorrentes, tutoriais, guias populares.

5. Retorne obrigatoriamente dados estruturados em JSON:

{
  "profissao": "nome",
  "area": "área de atuação",
  "cbo_codigo": "CBO completo",
  "cbo_descricao": "descrição oficial",
  "url_curso": "${link}",
  "whatsapp": "55DDNUMERO",
  "kpis": {
    "faturamento_setor": "R$ XX bilhões (fonte)",
    "empregos_formais": "XXX mil (fonte)",
    "crescimento_anual": "+X,XX% (fonte)",
    "empresas_pdvs": "XX.XXX (fonte)"
  },
  "salarios": {
    "piso": "R$ X.XXX", "media": "R$ X.XXX", "teto": "R$ X.XXX", "especialista": "R$ XX.XXX",
    "fonte": "CAGED/Glassdoor/Salario.com.br", "periodo": "2024-2026",
    "por_estado": [
      {"estado": "SP", "salario": "R$ X.XXX"},{"estado": "RJ", "salario": "R$ X.XXX"},
      {"estado": "MG", "salario": "R$ X.XXX"},{"estado": "PR", "salario": "R$ X.XXX"},
      {"estado": "RS", "salario": "R$ X.XXX"},{"estado": "BA", "salario": "R$ X.XXX"},
      {"estado": "SC", "salario": "R$ X.XXX"}
    ]
  },
  "tendencias": [
    {"titulo": "T1", "descricao": "2-3 frases com dado numérico"},
    {"titulo": "T2", "descricao": "..."},{"titulo": "T3", "descricao": "..."},
    {"titulo": "T4", "descricao": "..."},{"titulo": "T5", "descricao": "..."},
    {"titulo": "T6", "descricao": "..."}
  ],
  "atribuicoes": [
    {"titulo": "A1", "descricao": "desc", "emoji": "e"},{"titulo": "A2", "descricao": "...", "emoji": "..."},
    {"titulo": "A3", "descricao": "...", "emoji": "..."},{"titulo": "A4", "descricao": "...", "emoji": "..."}
  ],
  "faq": [
    {"pergunta": "Qual salário?", "resposta": "Com dados reais"},
    {"pergunta": "Duração do curso?", "resposta": "6 meses, 320h, online, MEC."},
    {"pergunta": "Mercado em alta?", "resposta": "Com KPI"},
    {"pergunta": "Regulação?", "resposta": "Com base legal"},
    {"pergunta": "Precisa ensino médio?", "resposta": "Sim."},
    {"pergunta": "Extra YouTube/Reddit?", "resposta": "Completa"}
  ],
  "contexto_profissao": "3-4 parágrafos",
  "citacao_impactante": "frase forte",
  "citacao_fonte": "fonte",
  "regulacao": {"orgao": "órgão", "exigencias": "exigências"},
  "diferencial_curso": "diferencial UFEM",
  "fontes_dados": ["fontes"],
  "slug_seo": "slug-otimizado-seo-sem-acentos-maximo-5-palavras-com-keyword-principal",
  "insights_audiencia": {
    "top_duvidas_youtube": ["10 dúvidas"],
    "top_temas_reddit": ["5 temas"],
    "dores_e_desejos": ["dores e desejos"]
  }
}

6. Identifique termos do nicho com alto volume em Shorts/TikTok/Reels.
7. Use comentários engajados para FAQ e insights_audiencia.
</INSTRUCOES>

IMPORTANTE: Retorne dossiê completo E JSON ao final. Dados reais, fontes identificáveis, 2024-2026.`;

const requestBody = {
  model: 'gpt-5.4-mini',
  tools: [{ type: 'web_search' }],
  instructions: 'Pesquisador de mercado especializado em profissões técnicas no Brasil. Pesquise profundamente na web. SEMPRE inclua JSON estruturado ao final. Fontes oficiais brasileiras. Dados reais.',
  input: userPrompt,
  max_output_tokens: 8000
};

return [{ json: { ...data, requestBody } }];

const response = $input.first().json;
const prev = $('Montar Perplexity').first().json;

const messageItem = (response.output || []).find(i => i.type === 'message');
const content = messageItem
  ? messageItem.content.filter(c => c.type === 'output_text').map(c => c.text).join('\n')
  : (response.output_text || '');
const citations = messageItem
  ? messageItem.content.flatMap(c => (c.annotations || []).filter(a => a.type === 'url_citation').map(a => a.url))
  : [];

let pesquisa = null;
let dossie = content;

const jsonMatches = content.match(/\{[\s\S]*?"profissao"[\s\S]*?\}/g);
if (jsonMatches && jsonMatches.length > 0) {
  let best = jsonMatches[0];
  for (const m of jsonMatches) { if (m.length > best.length) best = m; }
  try {
    pesquisa = JSON.parse(best.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
  } catch(e) {
    try {
      const lb = content.lastIndexOf('}');
      const fb = content.lastIndexOf('{', content.lastIndexOf('"profissao"'));
      if (fb !== -1) pesquisa = JSON.parse(content.substring(fb, lb + 1));
    } catch(e2) {}
  }
  if (pesquisa) {
    const idx = content.indexOf(best);
    if (idx > 0) dossie = content.substring(0, idx).trim();
  }
}

if (!pesquisa) pesquisa = { profissao: prev.curso, area: prev.curso, url_curso: prev.link, whatsapp: '55DDNUMERO' };
pesquisa.url_curso = pesquisa.url_curso || prev.link;
pesquisa.profissao = pesquisa.profissao || prev.curso;
pesquisa.whatsapp = pesquisa.whatsapp || '55DDNUMERO';

return [{ json: {
  curso: prev.curso, link: prev.link, rowIndex: prev.rowIndex,
  apiKey: prev.apiKey, wpUrl: prev.wpUrl, sheetsUrl: prev.sheetsUrl,
  systemPromptB64: prev.systemPromptB64,
  pesquisa, pesquisa_json: JSON.stringify(pesquisa, null, 2),
  dossie_completo: dossie
}}];

const response = $input.first().json;
const prev = $('Montar Claude').first().json;

let html = '';
if (response.content && Array.isArray(response.content)) {
  html = response.content.filter(b => b.type === 'text').map(b => b.text).join('');
} else if (typeof response.content === 'string') {
  html = response.content;
}
html = html.replace(/```html\n?/g, '').replace(/```\n?/g, '').trim();

// Remover qualquer <style> que o Claude tenha gerado por engano + dark mode
html = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
html = html.replace(/<button[^>]*nav__theme[^>]*>[\s\S]*?<\/button>/gi, '');
html = html.replace(/data-theme="[^"]*"/gi, 'data-theme="light"');
html = html.replace(/\[data-theme="dark"\]\s*\{[\s\S]*?\}/gi, '');
html = html.replace(/<script[\s\S]*?toggleTheme[\s\S]*?<\/script>/gi, '');
html = html.replace(/<script[\s\S]*?data-theme[\s\S]*?<\/script>/gi, '');

// CSS canonico mora no tema (Aparencia > Personalizar > CSS adicional).
// O Claude NAO gera mais CSS: a pagina entrega apenas o HTML com as classes.

let bodyContent = html;
const bodyMatch = html.match(/<body[^>]*>([\s\S]*)<\/body>/i);
if (bodyMatch) bodyContent = bodyMatch[1].trim();

let schemaBlocks = '';
const schemaMatches = html.match(/<script type="application\/ld\+json">[\s\S]*?<\/script>/gi);
if (schemaMatches) schemaBlocks = schemaMatches.join('\n');

const wpContent = `<!-- wp:html -->
${schemaBlocks}
<div class="page-wrap">
${bodyContent}
</div>
<!-- /wp:html -->`;

// === SEO RANKMATH ===
const curso = prev.curso || 'curso';
const wpUrl = prev.wpUrl || '';
const profissao = prev.pesquisa?.profissao || curso;

// Helper: normaliza string para slug-friendly (sem acento, lowercase)
const normalizar = (s) => String(s).toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .trim();

// Slug do post (URL): sem acento, sem ano, com hifens.
// Ex: profissao = "Tecnico em Confeitaria" -> slug = "tecnico-em-confeitaria"
const profClean = normalizar(profissao)
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '');
const slug = (prev.pesquisa?.slug_seo || profClean)
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .replace(/-?20\d{2}$/, '');

// FOCUS KEYWORD: SEM ACENTO, lowercase, com espacos.
// Ex: "tecnico em confeitaria". RankMath compara strings normalizadas e o slug eh sem acento,
// entao a focus kw tambem precisa ser sem acento para bater 100%.
const focusKw = normalizar(profissao);

// SECONDARY KEYWORDS (RankMath suporta varias secundarias para reforcar):
// Versao com acento (como aparece no texto), versao com ano, e variacoes naturais.
const secondaryKws = [
  profissao.toLowerCase().trim(),                         // com acento
  `${normalizar(profissao)} 2026`,                        // com ano
  `curso de ${normalizar(profissao)}`,                    // com prefixo
  `${normalizar(profissao)} salario`                      // long-tail
].filter((v, i, a) => v && a.indexOf(v) === i).join(',');

// SEO TITLE: comeca com a profissao
const seoTitle = `${profissao}: Salario, Mercado e Curso 2026`;

// META DESCRIPTION
let metaDesc = '';
const m = html.match(/<meta\s+name="description"\s+content="([^"]+)"/i);
if (m) metaDesc = m[1].trim();

// Validacao: a meta deve conter a kw NORMALIZADA (sem acento) para o RankMath validar.
const metaContemKw = normalizar(metaDesc).includes(focusKw);
if (!metaDesc || !metaContemKw || metaDesc.length < 100 || metaDesc.length > 160) {
  metaDesc = `${profissao}: descubra salario, mercado de trabalho, atribuicoes e o curso EAD da UFEM com certificacao MEC. Forme-se em ate 12 meses.`;
  if (metaDesc.length > 155) metaDesc = metaDesc.substring(0, 152) + '...';
}

const wpBody = JSON.stringify({
  title: seoTitle,
  slug: slug,
  content: wpContent,
  status: 'publish',
  meta: {
    rank_math_title: seoTitle,
    rank_math_description: metaDesc,
    rank_math_focus_keyword: focusKw,
    rank_math_secondary_keywords: secondaryKws
  }
});

return [{ json: {
  wp_url: wpUrl,
  wp_body: wpBody,
  sheetsUrl: prev.sheetsUrl,
  rowIndex: prev.rowIndex,
  curso: prev.curso,
  _seo_debug: {
    focusKw,
    secondaryKws,
    seoTitle,
    metaDesc,
    metaContemKw,
    metaLength: metaDesc.length,
    slug
  }
}}];

// Preparar dados para marcar linha como "ok" na planilha
const prev = $('Extrair HTML').first().json;
const wpResponse = $input.first().json;

return [{ json: {
  rowIndex: prev.rowIndex,
  sheetsUrl: prev.sheetsUrl,
  curso: prev.curso,
  postUrl: wpResponse.link || wpResponse.guid?.rendered || '',
  postId: wpResponse.id || ''
}}];

// PROMPT LIMPO: gera SO a foto editorial, sem nenhum texto.
// O texto da capa sera renderizado depois via HTML+Screenshot (texto perfeito, com acento).

const wpResponse = $input.first().json;
const prev = $('Extrair HTML').first().json;
const postId = wpResponse.id;
const wpUrl = prev.wp_url;
const curso = prev.curso || 'Curso Tecnico';

const poses = [
  'standing confidently with arms crossed, looking at camera',
  'working hands-on with equipment, focused on the task, side profile',
  'walking through the workplace, dynamic movement, captured mid-stride',
  'sitting at a workstation analyzing data on a screen, three-quarter view',
  'crouching while inspecting equipment, low angle shot looking up',
  'pointing at something off-camera while explaining, candid moment',
  'holding professional tools, close-up from waist up, slight smile',
  'leaning against a wall in uniform, relaxed professional pose, full body'
];

const angles = [
  'shot from slightly below, empowering angle',
  'eye-level medium shot',
  'wide angle environmental portrait',
  'shallow depth of field, subject sharp, background blurred',
  'over-the-shoulder perspective showing the workspace',
  'cinematic close-up, upper body framing'
];

const demographics = [
  'young Brazilian woman with dark hair',
  'middle-aged Brazilian man with short beard',
  'young Brazilian man, clean-shaven',
  'Brazilian woman with curly hair, mid-30s',
  'older experienced Brazilian professional, gray hair',
  'young Afro-Brazilian professional',
  'Brazilian woman wearing glasses, confident expression',
  'athletic Brazilian man in his late 20s'
];

const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

const imagePrompt = `Professional editorial photograph for a blog cover, 1200x720 pixels, 16:9 aspect ratio. Subject: ${pick(demographics)}, ${pick(poses)}, working as a ${curso} professional in their authentic work environment. ${pick(angles)}. Natural lighting, editorial photography style, photorealistic, high quality. IMPORTANT COMPOSITION RULE: position the main subject on the LEFT 60% of the frame. The RIGHT 40% of the frame must be a clean, less-detailed background area (out of focus, smooth wall, sky, or shallow workspace) with NO subjects, NO text, NO logos, NO signs, NO labels, NO numbers, NO watermarks. The right side will be used later for design overlay. Do not render any text anywhere in the image.`;

const __pollSeed = Math.floor(Math.random() * 1e9);
const fotoUrl = 'https://gen.pollinations.ai/image/' + encodeURIComponent(imagePrompt) + '?width=1280&height=720&model=flux&nologo=true&seed=' + __pollSeed;

return [{ json: {
  imagePrompt,
  fotoUrl,
  postId,
  wpUrl,
  curso,
  sheetsUrl: prev.sheetsUrl,
  rowIndex: prev.rowIndex
}}];

// Recebe a foto pura do Pollinations e passa para o proximo passo (Montar HTML Capa).
const result = $input.first().json;
const dados = $('Gerar Prompt Imagem').first().json;

if (!result.secure_url) {
  return [{ json: {
    rowIndex: dados.rowIndex,
    sheetsUrl: dados.sheetsUrl,
    curso: dados.curso,
    postUrl: '',
    postId: dados.postId,
    imagemStatus: 'falhou ou ainda processando'
  }}];
}

const fotoUrl = result.secure_url;

return [{ json: {
  fotoUrl,
  postId: dados.postId,
  wpUrl: dados.wpUrl,
  curso: dados.curso,
  rowIndex: dados.rowIndex,
  sheetsUrl: dados.sheetsUrl
}}];

// PONTO DE ENTRADA: recebe dados do node 'WordPress Post' e 'Processar Pesquisa'
// Na pipeline original, conecte este node logo após 'WordPress Post'

const wpResponse = $input.first().json;
const pesquisaNode = $('Processar Pesquisa').first().json;
const extrairNode = $('Extrair HTML').first().json;

const postUrl  = wpResponse.link || wpResponse.guid?.rendered || '';
const postId   = wpResponse.id || '';
const wpUrl    = extrairNode.wp_url || '';
const curso    = extrairNode.curso  || '';
const pesquisa = pesquisaNode.pesquisa || {};

// Dados estruturados vindos do Perplexity
const profissao   = pesquisa.profissao  || curso;
const area        = pesquisa.area       || curso;
const kpis        = pesquisa.kpis       || {};
const salarios    = pesquisa.salarios   || {};
const tendencias  = pesquisa.tendencias || [];
const atribuicoes = pesquisa.atribuicoes|| [];
const faq         = pesquisa.faq        || [];
const urlCurso    = pesquisa.url_curso  || extrairNode.link || '';

return [{ json: {
  curso,
  profissao,
  area,
  postUrl,
  postId,
  wpUrl,
  urlCurso,
  kpis,
  salarios,
  tendencias,
  atribuicoes,
  faq,
  pesquisa_json: JSON.stringify(pesquisa, null, 2)
}}];

const d = $input.first().json;
const apiKey = $('Config').first().json.ANTHROPIC_API_KEY;

const ehPos = /pos\.ufem|pos-graduacao|\/pos\//i.test(String(d.urlCurso || '') + ' ' + String(d.postUrl || ''));
const tipoTxt = ehPos ? 'PÓS-GRADUAÇÃO' : 'GRADUAÇÃO TECNÓLOGA';
const durRef  = ehPos ? '3 a 6 meses' : '18 meses (alguns cursos 24 ou 30; use o que a pesquisa indicar, senão 18)';

const userMessage = `Você cria o conteúdo de um carrossel institucional da UFEM para UM curso, no padrão editorial da marca. NÃO é narrativa de vendas: é informativo, direto e elegante.

CURSO: ${d.profissao}
ÁREA: ${d.area}
TIPO: ${tipoTxt}
DURAÇÃO DE REFERÊNCIA: ${durRef}
URL DO CURSO: ${d.urlCurso}
URL DO BLOG (story): ${d.postUrl}

PESQUISA DISPONÍVEL (use para competências e números, não invente):
${d.pesquisa_json}

O template já tem os slides fixos do modelo (capa, números, atalhos ou pontos em concurso e progressão, e CTA). Você só precisa do conteúdo específico do curso abaixo.

REGRAS:
- Português correto e com acentuação.
- PROIBIDO o caractere travessão (—). Use vírgula, dois pontos ou ponto.
- SEM emojis em qualquer campo, exceto nas duas legendas (caption_carrossel e caption_story).
- Competências: 6 a 10 itens curtos (3 a 6 palavras), reais e específicos do curso, tirados da pesquisa. Nada genérico como "fundamentos da área".
- Números: use só o que a pesquisa sustenta. NÃO invente salário. Se não houver número seguro, foque na duração e na modalidade.
- Frases curtas, tom editorial. Evite "nesse sentido", "ademais", "é importante destacar".

RETORNE APENAS JSON VÁLIDO, sem markdown, sem texto antes ou depois:

{
  "hook": {
    "tag": "linha curta de gancho, no máximo 9 palavras",
    "subtitulo": "tagline curta para destaque em laranja, no máximo 7 palavras",
    "lead": "uma frase resumindo o curso, a modalidade e o diploma"
  },
  "competencias": ["...", "...", "...", "...", "...", "..."],
  "numero": {
    "destaque": "${ehPos ? '3 a 6' : '18'}",
    "unidade": "meses",
    "apoio": "uma frase de contexto sobre a duração ou o diferencial do curso"
  },
  "story": {
    "eyebrow": "CONFIRA O ARTIGO COMPLETO",
    "titulo": "${d.profissao}: salários, mercado e como se formar",
    "dado_destaque": "o dado mais impactante e defensável do setor, vindo da pesquisa",
    "cta": "LINK NA BIO"
  },
  "caption_carrossel": "legenda completa para o carrossel, até 2200 caracteres, pode ter emojis e hashtags ao final, com CTA para o link na bio",
  "caption_story": "legenda curta para o story, até 150 caracteres"
}`;

return [{ json: {
  ...d,
  apiKey,
  requestBody: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 4000,
    temperature: 0.4,
    messages: [{ role: 'user', content: userMessage }]
  }
}}];

// Parseia a resposta do Claude e extrai o JSON do roteiro
const response = $input.first().json;
const prev = $('Montar Roteiro Claude').first().json;

let text = '';
if (response.content && Array.isArray(response.content)) {
  text = response.content.filter(b => b.type === 'text').map(b => b.text).join('');
}
text = text.replace(/```json\s*/gi, '').replace(/```/g, '').trim();

// Extrai o PRIMEIRO objeto { } balanceado, ignorando chaves dentro de strings.
// Resolve "lixo depois do JSON" (o modelo as vezes escreve texto apos o objeto).
function extractObject(s) {
  const start = s.indexOf('{');
  if (start === -1) return s;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < s.length; i++) {
    const c = s[i];
    if (esc) { esc = false; continue; }
    if (c === '\\') { esc = true; continue; }
    if (c === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return s.substring(start, i + 1); }
  }
  return s.substring(start);
}

// Escapa caracteres de controle crus dentro de strings + remove virgula pendurada
function repair(s) {
  let out = '', inStr = false, esc = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (esc) { out += c; esc = false; continue; }
    if (c === '\\') { out += c; esc = true; continue; }
    if (c === '"') { inStr = !inStr; out += c; continue; }
    if (inStr && c.charCodeAt(0) < 0x20) {
      if (c === '\n') out += '\\n';
      else if (c === '\r') out += '\\r';
      else if (c === '\t') out += '\\t';
      else if (c === '\b') out += '\\b';
      else if (c === '\f') out += '\\f';
      else out += '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0');
      continue;
    }
    out += c;
  }
  return out.replace(/,(\s*[}\]])/g, '$1');
}

const obj = extractObject(text);
let roteiro = null, parseErr = '';
for (const cand of [obj, repair(obj)]) {
  try { roteiro = JSON.parse(cand); break; } catch (e) { parseErr = e.message; }
}

