const ehPos = /pos\.ufem|pos-graduacao|\/pos\//i.test(String(d.urlCurso || '') + ' ' + String(d.postUrl || ''));

const __pollDims = { '1:1': [1024, 1024], '16:9': [1280, 720], '9:16': [720, 1280] };
function pollUrl(prompt, size) {
  const dim = __pollDims[size] || [1024, 1024];
  const seed = Math.floor(Math.random() * 1e9);
  return 'https://gen.pollinations.ai/image/' + encodeURIComponent(prompt) + '?width=' + dim[0] + '&height=' + dim[1] + '&model=flux&nologo=true&seed=' + seed;
}

// Prompts tematicos de AMBIENTE (sem pessoas/rostos), para nao ficar com cara de IA falsa
const base = 'Photorealistic editorial photograph, professional, natural cinematic lighting, shallow depth of field, NO people, no faces, no hands, no text, no logos, no watermarks, high detail.';
function promptFor(role, prof) {
  const map = {
    capa:   `${base} A striking modern workplace environment related to ${prof}: clean organized desk, screens or tools of the trade, bright and aspirational, wide editorial composition.`,
    split1: `${base} Close-up detail of professional tools, equipment or instruments related to ${prof}, on a workbench or desk, crisp focus, moody background.`,
    split2: `${base} A calm modern professional workspace related to ${prof}: laptop, documents and objects organized on a desk by a window, warm daylight.`,
    grade:  `${base} Wide editorial photograph of a real ${prof} working environment: characteristic equipment, instruments and setting of this profession, rich authentic detail, cinematic horizontal composition, moody ambient light.`,
    cta:    `${base} An inspiring modern office, studio or campus environment related to ${prof}, golden hour light, sense of achievement, depth and atmosphere.`,
    story:  `${base} Dramatic wide-angle of a modern ${prof} environment, golden hour, impressive architecture or equipment, cinematic vertical composition.`
  };
  return map[role] || map.capa;
}

// Papeis por tipo: tecnologo usa 2 splits; pos so capa e cta. Story sempre.
const roles = ehPos ? ['capa', 'grade', 'cta'] : ['capa', 'grade', 'split1', 'split2', 'cta'];

const items = [];
for (const role of roles) {
  const p = promptFor(role, profissao);
  items.push({ json: {
    num:      role,
    tipo:     role,
    prompt:   p,
    size:     '1:1',
    imageUrl: pollUrl(p, '1:1')
  }});
}

const ps = promptFor('story', profissao);
items.push({ json: {
  num:      'story',
  tipo:     'story',
  prompt:   ps,
  size:     '9:16',
  imageUrl: pollUrl(ps, '9:16')
}});

return items;

const result = $input.item.json;

const allPrompts = $('Gerar Prompts Imagens').all();
const idx = $itemIndex;
const promptItem = allPrompts[idx]?.json || {};

const imageUrl = result.secure_url || null;

return {
  num:      promptItem.num || String(idx + 1),
  tipo:     promptItem.tipo || 'unknown',
  imageUrl
};

const inputData = $input.first().json;

let items = [];
if (Array.isArray(inputData.slides_com_imagens)) {
  items = inputData.slides_com_imagens;
} else {
  items = $input.all().map(i => i.json);
}

const prev = $('Processar Roteiro').first().json;

const imageMap = {};
for (const item of items) {
  const num = item.num;
  const url = item.imageUrl || null;
  if (num !== undefined && url) {
    imageMap[String(num)] = url;
  }
}

console.log('imageMap keys:', Object.keys(imageMap));

return [{ json: {
