const HANDLE = '@ufem.educacional';
const CSS = "\n@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');\n:root{\n  --warm:#faf8f5; --ink:#15172b; --ink2:#5f6178;\n  --cream:#f2ede6; --cream2:#9698ab;\n  --accent:#ea7327;\n  --lw:rgba(21,23,43,.13); --ld:rgba(255,255,255,.12);\n}\n*{margin:0;padding:0;box-sizing:border-box}\n.slide{position:relative;width:1080px;height:1440px;overflow:hidden;\n  font-family:'Inter',sans-serif;-webkit-font-smoothing:antialiased;text-rendering:geometricPrecision}\n.warm{background:var(--warm);color:var(--ink)}\n.dark{background:#0b0a14;color:var(--cream)}\n.dark.glow::before{content:\"\";position:absolute;inset:0;z-index:0;\n  background:radial-gradient(125% 105% at 10% -8%, #3a2420 0%, #1b1626 42%, #0a0913 100%)}\n/* foto + overlay */\n.ph{position:absolute;inset:0;z-index:0}\n.ph img{width:100%;height:100%;object-fit:cover;display:block}\n.ovl{position:absolute;inset:0;z-index:1}\n/* faixa split-screen (foto contida em um lado) */\n.band{position:absolute;top:0;bottom:0;z-index:1;overflow:hidden}\n.band>img{width:100%;height:100%;object-fit:cover;display:block}\n.feL{position:absolute;left:0;top:0;bottom:0;width:96px}\n.feR{position:absolute;right:0;top:0;bottom:0;width:86px}\n/* legibilidade de tarjas sobre foto */\n#slide-07 .pag,#slide-07 .nx{text-shadow:0 1px 7px rgba(0,0,0,.7)}\n#slide-08 .eb{text-shadow:0 1px 9px rgba(250,248,245,.85),0 0 2px rgba(250,248,245,.7)}\n#slide-08 .hd{text-shadow:0 1px 5px rgba(0,0,0,.55),0 0 2px rgba(0,0,0,.4)}\n#slide-06 .nx{color:#4a4c62;text-shadow:0 1px 6px rgba(250,248,245,.7),0 1px 3px rgba(0,0,0,.25)}\n#slide-02 .kc .l{color:#3d3f55;font-weight:600;text-shadow:0 1px 5px rgba(250,248,245,.6)}\n#slide-02 .kc .v{text-shadow:0 1px 7px rgba(250,248,245,.5)}\n#slide-02 .hd{text-shadow:0 1px 7px rgba(250,248,245,.75)}\n#slide-02 .nx{color:#54566c;text-shadow:0 1px 7px rgba(250,248,245,.65)}\n/* tarjas */\n.s-top{position:absolute;top:50px;left:74px;right:74px;display:flex;justify-content:space-between;align-items:center;z-index:30}\n.eb{display:flex;align-items:center;gap:13px;font-size:21px;font-weight:700;letter-spacing:2.4px;text-transform:uppercase}\n.eb .d{width:11px;height:11px;border-radius:50%;background:var(--accent);flex:none}\n.warm .eb{color:var(--ink)} .dark .eb{color:var(--cream)}\n.pag{font-size:23px;font-weight:800;letter-spacing:1px}\n.pag b{color:var(--accent)}\n.warm .pag{color:var(--ink2)} .dark .pag{color:var(--cream2)}\n.rule{position:absolute;top:93px;left:74px;right:74px;height:1px;z-index:30}\n.warm .rule{background:var(--lw)} .dark .rule{background:var(--ld)}\n.s-bot{position:absolute;bottom:52px;left:74px;right:74px;display:flex;justify-content:space-between;align-items:center;z-index:30}\n.hd{font-size:24px;font-weight:800;color:var(--accent)}\n.nx{display:flex;align-items:center;gap:11px;font-size:19px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase}\n.warm .nx{color:var(--ink2)} .dark .nx{color:var(--cream2)}\n.nx .tri{margin-left:2px}\n/* conteudo */\n.ct{position:absolute;left:74px;right:74px;z-index:20}\n/* secao */\n.sec{display:flex;align-items:baseline;gap:13px}\n.sec .n{font-size:44px;font-weight:900;color:var(--accent);letter-spacing:-1px;line-height:1}\n.sec .l{font-size:21px;font-weight:700;letter-spacing:2.8px;text-transform:uppercase}\n.warm .sec .l{color:var(--ink2)} .dark .sec .l{color:var(--cream2)}\n/* titulo */\n.h1{font-weight:900;letter-spacing:-2.5px;line-height:1.0}\n.h1 em{font-style:normal;color:var(--accent)}\n.lead{font-weight:400;line-height:1.42}\n.warm .lead{color:#3c3e54} .dark .lead{color:#cdd0e0}\n.divs{width:64px;height:4px;background:var(--accent);border-radius:2px}\n/* monumento */\n.mono{display:flex;align-items:center;gap:20px}\n.mono .n{font-size:210px;font-weight:900;color:var(--accent);line-height:.74;letter-spacing:-8px}\n.mono .u{font-size:54px;font-weight:800}\n.warm .mono .u{color:var(--ink)} .dark .mono .u{color:var(--cream)}\n/* kpi strip */\n.kpi{display:flex}\n.kc{flex:1;padding:0 24px;border-left:1px solid var(--lw)}\n.kc:first-child{padding-left:0;border-left:none}\n.kc .v{font-size:50px;font-weight:900;color:var(--accent);line-height:1;letter-spacing:-1px}\n.kc .l{font-size:18px;font-weight:500;color:var(--ink2);margin-top:9px;line-height:1.22}\n/* grade */\n.cat{display:flex;align-items:center;gap:16px;margin:24px 0 8px}\n.cat .t{font-size:22px;font-weight:800;letter-spacing:1.8px;text-transform:uppercase;color:var(--accent);white-space:nowrap}\n.cat .c{font-size:22px;font-weight:800;letter-spacing:1.8px;color:var(--accent);opacity:.62;white-space:nowrap}\n.cat .ln{flex:1;height:1px}\n.warm .cat .ln{background:var(--lw)} .dark .cat .ln{background:var(--ld)}\n.grid{display:grid;grid-template-columns:1fr 1fr;column-gap:48px}\n.row{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;padding:15px 0;border-bottom:1px solid}\n.warm .row{border-color:var(--lw)} .dark .row{border-color:var(--ld)}\n.row .nm{font-size:30px;font-weight:700;line-height:1.18}\n.row .du{font-size:18px;font-weight:700;letter-spacing:.5px;white-space:nowrap;padding-top:5px}\n.warm .row .du{color:var(--ink2)} .dark .row .du{color:var(--cream2)}\n.cbadge{text-align:right;flex:none}\n.cbadge .cn{font-size:80px;font-weight:900;color:var(--accent);line-height:.85;letter-spacing:-3px}\n.cbadge .cl{font-size:20px;font-weight:700;letter-spacing:3px;text-transform:uppercase;margin-top:2px}\n.warm .cbadge .cl{color:var(--ink2)} .dark .cbadge .cl{color:var(--cream2)}\n/* pill */\n.pill{display:inline-block;padding:9px 16px;font-size:18px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:#fff;border-radius:3px}\n.pill.red{background:#c63a28} .pill.org{background:#bd6a22}\n/* tag box (hero) */\n.tagbox{display:inline-block;border:1.6px solid rgba(234,115,39,.75);color:var(--accent);\n  padding:11px 18px;font-size:19px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase;border-radius:3px}\n/* big num hero */\n.bn{font-size:240px;font-weight:900;color:var(--accent);line-height:.78;letter-spacing:-8px}\n.bn-u{font-size:22px;font-weight:800;letter-spacing:4px;text-transform:uppercase;color:var(--cream)}\n/* cards */\n.card{border-radius:5px;padding:24px 28px}\n.card .ch{display:flex;align-items:baseline;gap:11px;margin-bottom:9px}\n.card .big{font-size:40px;font-weight:900;color:var(--accent);line-height:1}\n.card .hl{font-size:27px;font-weight:800}\n.card .bd{font-size:22px;line-height:1.38}\n.card.d{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1)}\n.card.d .hl{color:var(--cream)} .card.d .bd{color:var(--cream2)}\n.card.w{background:#fff;border:1px solid rgba(21,23,43,.1);box-shadow:0 8px 26px rgba(21,23,43,.06)}\n.card.w .hl{color:var(--ink)} .card.w .bd{color:var(--ink2)}\n.star{color:var(--accent);font-size:30px;line-height:1}\n/* combo + callout + checks (slide 09) */\n.combo{display:flex;align-items:center;gap:26px;background:rgba(255,255,255,.045);\n  border:1px solid rgba(255,255,255,.1);border-radius:6px;padding:26px 30px}\n.combo .blk{display:flex;align-items:baseline;gap:12px}\n.combo .pc{font-size:46px;font-weight:900;color:var(--accent);line-height:1}\n.combo .tx{font-size:21px;font-weight:600;color:var(--cream2);line-height:1.3}\n.combo .plus{font-size:38px;font-weight:800;color:var(--cream2)}\n.callout{border-left:4px solid var(--accent);border-radius:0 5px 5px 0;padding:22px 26px;\n  background:linear-gradient(90deg, rgba(234,115,39,.13), rgba(234,115,39,.02))}\n.callout .ce{font-size:18px;font-weight:800;letter-spacing:2px;text-transform:uppercase;color:var(--accent);margin-bottom:9px}\n.callout .cb{font-size:24px;font-weight:500;line-height:1.36;color:var(--cream)}\n.subh{font-size:34px;font-weight:900;letter-spacing:-1px;color:var(--cream)}\n.chk{display:flex;gap:18px;padding:15px 0;border-bottom:1px solid var(--ld)}\n.chk .ic{width:38px;height:38px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center;flex:none;margin-top:2px}\n.chk .ti{font-size:27px;font-weight:800;color:var(--cream);line-height:1.1}\n.chk .de{font-size:21px;font-weight:500;color:var(--cream2);line-height:1.32;margin-top:3px}\n/* pointer + meta + save */\n.point{display:flex;align-items:center;gap:14px;color:var(--accent);font-size:25px;font-weight:800}\n.meta{font-weight:500;line-height:1.45}\n.warm .meta{color:var(--ink2)} .dark .meta{color:var(--cream2)}\n.save{display:flex;align-items:center;gap:13px;color:var(--accent);font-size:32px;font-weight:900;letter-spacing:-.5px}\n.foot-cta{font-size:21px;font-weight:700;line-height:1.5;color:var(--cream2)}\n.foot-cta b{color:var(--accent);font-weight:800}\n\n.slide{height:1350px}\n.warm .chk{border-color:var(--lw)} .warm .chk .ti{color:var(--ink)} .warm .chk .de{color:var(--ink2)}\n#slide-01 .eb,#slide-01 .pag,#slide-01 .hd,#slide-01 .nx{text-shadow:0 1px 8px rgba(0,0,0,.6)}\n#slide-04 .pag,#slide-04 .nx{text-shadow:0 1px 7px rgba(0,0,0,.7)}\n#slide-03 .hd,#slide-03 .nx{text-shadow:0 1px 8px rgba(0,0,0,.65)}\n#slide-05 .eb{text-shadow:0 1px 9px rgba(250,248,245,.85),0 0 2px rgba(250,248,245,.7)}\n#slide-05 .hd{text-shadow:0 1px 5px rgba(0,0,0,.55),0 0 2px rgba(0,0,0,.4)}\n#slide-07 .eb,#slide-07 .pag,#slide-07 .nx,#slide-07 .foot-cta{text-shadow:0 1px 8px rgba(0,0,0,.6)}\n";

function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
