const OV_CTA  = "background:linear-gradient(100deg, #0b0a14 0%, #0b0a14 44%, rgba(11,10,20,.72) 58%, rgba(11,10,20,.32) 73%, rgba(11,10,20,0) 90%),radial-gradient(135% 100% at 0% 0%, rgba(58,35,32,.4) 0%, rgba(11,10,20,0) 55%)";

const kicker  = ehPos ? 'UFEM · Pós-graduação' : 'UFEM · Tecnólogo';
