  const lead = hook.lead || (ehPos
    ? 'Pós-graduação reconhecida pelo MEC, 100% online, conclusão em 3 a 6 meses.'
    : 'Graduação superior completa em 18 meses, 100% online e com diploma reconhecido pelo MEC.');
