const d = $('Preparar Carrossel').first().json;

const IG_USER_ID = 'IG_USER_ID';
const PAGE_TOKEN = 'META_PAGE_TOKEN_AQUI';
const API_VERSION = 'v22.0';

const storyUrl = d.storyUrl;
// Link sticker não é suportado pela API do Instagram
// O CTA visual "LINK NA BIO" é renderizado na imagem do story

if (!storyUrl) {
  throw new Error('storyUrl não encontrada em Preparar Carrossel');
}

const url = `https://graph.facebook.com/${API_VERSION}/${IG_USER_ID}/media`;

const params = {
  image_url: storyUrl,
  media_type: 'STORIES',
  access_token: PAGE_TOKEN,
};



const response = await this.helpers.httpRequest({
  method: 'POST',
  url: url,
  qs: params,
});

if (!response.id) {
  throw new Error('Falha ao criar container do story: ' + JSON.stringify(response));
}

return [{
  json: {
    story_container_id: response.id,
    ig_user_id: IG_USER_ID,
    page_token: PAGE_TOKEN,
    api_version: API_VERSION,
    storyUrl,
  }
}];

const config = $input.first().json;
const maxAttempts = 20;
const delayMs = 3000;

if (!config.api_version || !config.story_container_id || !config.page_token) {
  throw new Error('Campos faltando: ' + JSON.stringify({
    api_version: config.api_version,
    story_container_id: config.story_container_id,
    tem_token: !!config.page_token,
    tamanho_token: config.page_token ? String(config.page_token).length : 0
  }));
}

for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  const statusUrl = `https://graph.facebook.com/${config.api_version}/${config.story_container_id}`;
  let response;
  try {
    response = await this.helpers.httpRequest({
      method: 'GET',
      url: statusUrl,
      qs: {
        fields: 'status_code',
        access_token: config.page_token,
      },
    });
  } catch (error) {
    throw new Error('Graph API 400. Detalhe: ' + JSON.stringify({
      url: statusUrl,
      status: error.statusCode || error.response?.status,
      corpo: error.response?.data || error.response?.body || error.message,
      api_version_recebida: config.api_version,
      container_id_recebido: config.story_container_id
    }));
  }
  if (response.status_code === 'FINISHED') {
    return [{
      json: { ...config, container_status: 'FINISHED', attempts: attempt }
    }];
  }
  if (response.status_code === 'ERROR') {
    throw new Error('Container do story falhou: ' + JSON.stringify(response));
  }
  await new Promise(resolve => setTimeout(resolve, delayMs));
}
throw new Error(`Timeout: story nao ficou FINISHED apos ${maxAttempts} tentativas`);

const data = $input.first().json;
const url = `https://graph.facebook.com/${data.api_version}/${data.ig_user_id}/media_publish`;

const response = await this.helpers.httpRequest({
