// Monta HTML que ocupa 100vw x 100vh (Screenshot Service renderiza em 2160x2160)
// com um frame 16:9 centralizado verticalmente. Todas as medidas em vw para escalar
// proporcionalmente. O crop 16:9 final eh feito via transformacao Cloudinary na URL.
const d = $input.first().json;
const curso = d.curso || 'Curso';
const fotoUrl = d.fotoUrl;

if (!fotoUrl) {
  throw new Error('fotoUrl ausente no input do Montar HTML Capa Blog');
}

const tituloCapa = String(curso).toUpperCase();

// === QUEBRA INTELIGENTE EM 1, 2 OU 3 LINHAS ===
const splitTitulo = (txt) => {
  const words = txt.split(/\s+/).filter(Boolean);
  if (words.length === 1) return [words[0]];
  if (words.length === 2) return [words[0], words[1]];
  const conectivos = ['EM', 'DE', 'DA', 'DO', 'DAS', 'DOS', 'PARA', 'COM', 'E'];
  let breakIdx1 = -1;
  for (let i = 1; i < words.length; i++) {
    if (conectivos.includes(words[i])) { breakIdx1 = i + 1; break; }
  }
  if (breakIdx1 > 0 && breakIdx1 < words.length) {
    const linha1 = words.slice(0, breakIdx1).join(' ');
    const restoWords = words.slice(breakIdx1);
    const linha2Tudo = restoWords.join(' ');
    if (linha2Tudo.length > 18 && restoWords.length >= 3) {
      let breakIdx2 = -1;
      for (let i = 1; i < restoWords.length; i++) {
        if (conectivos.includes(restoWords[i])) { breakIdx2 = i; break; }
      }
      if (breakIdx2 > 0 && breakIdx2 < restoWords.length) {
        return [linha1, restoWords.slice(0, breakIdx2).join(' '), restoWords.slice(breakIdx2).join(' ')];
      }
      const mid = Math.ceil(restoWords.length / 2);
      return [linha1, restoWords.slice(0, mid).join(' '), restoWords.slice(mid).join(' ')];
    }
    return [linha1, linha2Tudo];
  }
  const mid = Math.ceil(words.length / 2);
  return [words.slice(0, mid).join(' '), words.slice(mid).join(' ')];
};

const linhas = splitTitulo(tituloCapa);
const numLinhas = linhas.length;

// === DIMENSIONAMENTO DAS FONTES EM vw ===
// Espaco util do text-block: 52vw - 4vw padding = ~48vw
// Numa viewport 16:9 de 100vw x 56.25vw, 48vw eh ~48% da largura
// Open Sans 900: ~0.60em por char em maiusculas, entao max chars que cabem = 48vw / (fontVw * 0.60)
// Resolvendo: fontVw = 48 / (chars * 0.60) = 80 / chars (em vw)
const LARGURA_UTIL_VW = 48;
const FATOR_CHAR = 0.60;

const calcFontVw = (texto, weight900 = true) => {
  if (!texto) return 6;
  const fator = weight900 ? FATOR_CHAR : FATOR_CHAR * 0.92;
  const fonteIdeal = LARGURA_UTIL_VW / (texto.length * fator);
  return Math.max(2.4, Math.min(fonteIdeal, 6.5));
};

let fontMain, fontSecond, fontThird;

if (numLinhas === 1) {
  fontMain = calcFontVw(linhas[0], true);
  fontMain = Math.min(fontMain, 6.5);
} else if (numLinhas === 2) {
  fontMain = calcFontVw(linhas[1], true);
  fontMain = Math.min(fontMain, 6.0);
  fontSecond = fontMain * 0.55;
  const maxSecondQueCabe = calcFontVw(linhas[0], false);
  fontSecond = Math.min(fontSecond, maxSecondQueCabe);
} else {
  const linhaMaisLonga = linhas[1].length > linhas[2].length ? linhas[1] : linhas[2];
  fontMain = calcFontVw(linhaMaisLonga, true);
  fontMain = Math.min(fontMain, 4.5);
  fontSecond = fontMain * 0.55;
  const maxSecondQueCabe = calcFontVw(linhas[0], false);
  fontSecond = Math.min(fontSecond, maxSecondQueCabe);
  fontThird = fontMain;
}

