// O Screenshot Service devolve PNG 2160x2160 com a capa 16:9 centralizada verticalmente.
// Usamos transformacao Cloudinary na URL para fazer crop centralizado em 16:9 -> 1200x720.
// Sintaxe: /upload/c_crop,ar_16:9,g_center/c_scale,w_1200/v.../...
// c_crop,ar_16:9 -> recorta para aspect ratio 16:9
// g_center -> mantem o centro
// c_scale,w_1200 -> redimensiona para 1200px de largura (altura proporcional = 675)
const response = $input.first().json;
const prev = $('Montar HTML Capa Blog').first().json;

const urls = response.imageUrls || response.urls || [];
if (!Array.isArray(urls) || urls.length === 0) {
  throw new Error('Screenshot Service nao devolveu imageUrls. Resposta: ' + JSON.stringify(response).substring(0, 500));
}

const rawUrl = urls[0];

// Injeta transformacao Cloudinary na URL.
// URL original: https://res.cloudinary.com/CLOUDINARY_CLOUD/image/upload/v123456/abc.png
// URL transformada: https://res.cloudinary.com/CLOUDINARY_CLOUD/image/upload/c_crop,ar_16:9,g_center/c_scale,w_1200/v123456/abc.png
const transformedUrl = rawUrl.replace(
  '/image/upload/',
  '/image/upload/c_crop,ar_16:9,g_center/c_scale,w_1200/'
);

return [{ json: {
  imageUrl: transformedUrl,
  rawUrl,
  postId: prev.postId,
  wpUrl: prev.wpUrl,
  curso: prev.curso,
  rowIndex: prev.rowIndex,
  sheetsUrl: prev.sheetsUrl
}}];
